css:
button {
  font-size: 17px;
  font-family: inherit;
  font-weight: 700;
  padding: 4px;
  border-radius: 20px;
  cursor: pointer;
  border: none;
  color: black;
  box-shadow: rgba(0, 0, 0, 0.1) 0px 20px 25px -5px,
    rgba(0, 0, 0, 0.04) 0px 10px 10px -5px;
  background: linear-gradient(0deg, #e4312b 0%, #000000 47%, #149954 100%);
}

button .button-content {
  display: flex;
  align-items: center;
  background: rgb(237, 255, 235);
  padding: 0.7em 1.5em;
  padding-left: 1.2em;
  border-radius: 16px;
}

button svg {
  width: 22px;
  height: 22px;
  margin-right: 6px;
  color: #000000;
  transition: transform 0.3s;
}

button:hover svg {
  transform: scale(1.2);
  color: #149954;
}
